import pytest
from calibration_target import Record

pytestmark = pytest.mark.verification_kind("unit")


@pytest.mark.verifies("CALIBRATION[revision==1]")
def test_summary_never_exposes_secret_at_level_zero():
    record = Record(name="session_profile", secret="super_secret_auth_token", level=0)
    summary = record.summary()
    assert "secret" not in summary
    assert summary == {"name": "session_profile"}
